package ts

import (
	"bytes"
	"fmt"
	"go/token"
	"path"
	"sort"
	"strings"

	"github.com/eugenioenko/goalchemy/internal/emit/artifact"
	"github.com/eugenioenko/goalchemy/internal/ir"
	"github.com/eugenioenko/goalchemy/internal/naming"
)

// Emit routes declarations while retaining one naming, representation and
// descriptor index for the entire source graph. Package modules contain live
// storage; canonical helpers form a leaf, and entry binds descriptors after
// all imported package declarations have loaded.
func Emit(p *ir.Program, symbols map[string]string) (*Output, error) {
	layout, err := artifact.NewLayout(p)
	if err != nil {
		return nil, err
	}
	entry := "main.ts"
	if p.Cooperative && !p.Library {
		entry = "program.ts"
	}
	e := &emitter{p: p, names: naming.New(p), symbols: symbols,
		contracts: map[string]bool{}, classes: map[*ir.Type]string{}, arrays: map[*ir.Type]bool{},
		tds: map[*ir.Type]string{}, seenHelp: map[*ir.Type]bool{}, locations: map[string]string{},
		globals: map[string]bool{}, imports: map[string]map[string]bool{}}
	bodies := map[string]*bytes.Buffer{"shared.ts": {}, entry: {}}
	owners := map[string]string{}
	paths := []string{"shared.ts"}
	for _, pkg := range layout.Packages {
		file := layout.Stem(pkg.Path) + ".ts"
		paths = append(paths, file)
		bodies[file] = &bytes.Buffer{}
		owners[file] = pkg.Path
	}
	paths = append(paths, entry)
	location := func(owner string) string {
		if owner == "" {
			return "shared.ts"
		}
		return layout.Stem(owner) + ".ts"
	}
	for _, f := range p.Funcs {
		file := location(f.Pkg)
		if f == p.Init || f == p.Entry {
			file = entry
		}
		e.locations[f.Sym] = file
	}
	for _, g := range p.Globals {
		e.locations[g.Sym] = location(g.Pkg)
		e.globals[g.Sym] = true
	}
	for _, t := range p.Types.All {
		if t.Boxed {
			e.td(t)
		}
	}
	// Every package owns a stable storage object. Reset mutates its slots (or
	// aggregate contents), so imported namespace references never go stale.
	for _, file := range paths {
		e.current = file
		b := bodies[file]
		if file == entry {
			continue
		}
		b.WriteString("export const $globals = {\n")
		for _, g := range p.Globals {
			if e.locations[g.Sym] != file {
				continue
			}
			z := e.zero(g.Type)
			if g.AddrTaken && !g.Type.IsAggregate() {
				z = "new rt.Cell<any>(" + z + ")"
			}
			fmt.Fprintf(b, "%s  %s: %s,\n", e.position(g.Pos), e.names.Symbol(g.Sym), z)
		}
		b.WriteString("};\n\n")
	}
	for _, f := range p.Funcs {
		file := e.locations[f.Sym]
		e.current = file
		fmt.Fprint(bodies[file], e.position(f.Pos), e.function(f))
		fmt.Fprintf(bodies[file], "(%s as any).$fid = %d;\n", e.names.Symbol(f.Sym), f.ID)
	}
	e.current = entry
	e.typeDescs(bodies[entry])
	if p.Library {
		api, err := e.library()
		if err != nil {
			return nil, &LibraryBoundaryError{Message: err.Error()}
		}
		bodies[entry].WriteString(api)
	} else if p.Cooperative {
		e.use("core.task.spawn")
		start := e.symbol(p.Entry.Sym) + "()"
		if !p.Entry.MaySuspend {
			start = "rt.sync(() => { " + e.symbol(p.Entry.Sym) + "(); return []; })"
		}
		fmt.Fprintf(bodies[entry], "\nexport function $run(): void { rt.runMain(%s); }\nexport function $runHost(host: rt.RuntimeHost = rt.runtimeHost): Promise<void> { return rt.runMainHost(%s, host); }\n", start, start)
	} else {
		fmt.Fprintf(bodies[entry], "\nrt.main(() => {\n  %s();\n", e.symbol(p.Init.Sym))
		if p.Main != nil {
			fmt.Fprintf(bodies[entry], "  %s();\n", e.symbol(p.Main.Sym))
		}
		bodies[entry].WriteString("});\n")
	}
	e.current = "shared.ts"
	e.flushHelpers()
	// Helpers never reference package functions or storage. Descriptors use a
	// registry read by function bodies only; entry assigns each descriptor once.
	if len(e.imports["shared.ts"]) != 0 {
		return nil, fmt.Errorf("canonical TypeScript support references a source module")
	}
	var helpers []string
	for _, n := range e.classes {
		helpers = append(helpers, n)
	}
	for t := range e.seenHelp {
		if t.Kind == ir.KArray {
			for _, prefix := range []string{"zero$", "clone$", "set$", "eq$", "key$"} {
				helpers = append(helpers, e.names.Type(t, prefix))
			}
		}
	}
	helpers = append(helpers, "$types")
	sort.Strings(helpers)
	var files []artifact.File
	for _, file := range paths {
		var b bytes.Buffer
		b.WriteString("// Code generated by goalchemy. DO NOT EDIT.\n// @ts-nocheck\n")
		if file == entry && !p.Cooperative && !p.Library {
			b.WriteString("import \"./rt/types/node_host.ts\";\n")
		}
		b.WriteString("import * as rt from \"./rt/index.ts\";\n")
		if file == "shared.ts" {
			b.WriteString("export const $types: Record<string, any> = {};\n\n")
			b.Write(e.helperOut.Bytes())
		} else {
			fmt.Fprintf(&b, "import { %s } from \"./shared.ts\";\n", strings.Join(helpers, ", "))
		}
		var dependencies []string
		for dependency := range e.imports[file] {
			dependencies = append(dependencies, dependency)
		}
		sort.Strings(dependencies)
		for _, dependency := range dependencies {
			fmt.Fprintf(&b, "import * as %s from \"./%s\";\n", moduleName(dependency), dependency)
		}
		b.WriteByte('\n')
		b.Write(bodies[file].Bytes())
		src, sm := e.resolveMarkers(b.String())
		sm.File = path.Base(file)
		if e.p.NoLineDirectives {
			sm = nil
		} else {
			src += "//# sourceMappingURL=" + path.Base(file) + ".map\n"
		}
		files = append(files, artifact.File{Path: file, Source: []byte(src), Owner: owners[file], SourceMap: sm})
	}
	var cs []string
	for c := range e.contracts {
		cs = append(cs, c)
	}
	sort.Strings(cs)
	return &Output{Files: files, Packages: layout.PackageFiles(files), Contracts: cs}, nil
}

func moduleName(file string) string { return "$module_" + strings.TrimSuffix(file, ".ts") }

func (e *emitter) position(pos token.Pos) string {
	if !pos.IsValid() {
		return ""
	}
	index := len(e.positions)
	e.positions = append(e.positions, ir.At{Pos: pos})
	return fmt.Sprintf("%s%d\x00", marker, index)
}
